# tests/test_validator.pyimport pytestimport osimport sysimport yamlimport json# Добавляем корень проекта в путь импортаsys.path.insert(0, os.path.join(os.path.dirname(__file__), '..'))def test_validator_config_integrity():    """Проверяет, что конфиг валидатора существует и содержит конституционные слои"""    config_path = os.path.join('validator', 'config', 'validator_config.yaml')    assert os.path.exists(config_path), "❌ validator_config.yaml not found"    with open(config_path, encoding='utf-8') as f:        config = yaml.safe_load(f)    assert 'pipeline' in config    assert 'stages' in config  # ✅ Исправлено: stages находится на верхнем уровне    assert all(k in config['stages'] for k in ['CoreCheck', 'GammaCheck', 'LanguageCheck', 'MetaCheck'])def test_bridge_contract_constitutional_fixes():    """Проверяет, что в мосте применены все 3 конституционных исправления"""    bridge_path = os.path.join('contracts', 'bridges', 'm4_bridge_contract.yaml')    assert os.path.exists(bridge_path), "❌ m4_bridge_contract.yaml not found"    with open(bridge_path, encoding='utf-8') as f:        contract = yaml.safe_load(f)    spec = contract['BridgeSpec']    # Исправление 1: Z_R.5    assert spec['role_binding_protocol']['mechanism'] == "co-emergent_constitution"    # Исправление 2: Γ_Locality    assert "intersection(agent.causal_window, engine.causal_window)" in spec['TPN_Signal_Protocol']['scope']    # Исправление 3: A0_multi + friction    assert "1 - Γ_friction_k" in spec['A0_multi_X_Economic_Resolver']['formula']    assert "Z_Invariant_Rollback" in spec['A0_multi_X_Economic_Resolver']['fallback']def test_sandbox_report_generation():    """Проверяет, что sandbox генерирует валидный JSON-отчёт"""    from validator.ts_d_sandbox import DSandbox    sandbox = DSandbox(iterations=5) # Быстрый прогон для теста    report = sandbox.run_selfplay()    assert os.path.exists('ts_sandbox_report.json')    with open('ts_sandbox_report.json') as f:        data = json.load(f)    assert 'valid_bindings' in data    assert 'epsilon_friction_recommended' in data    assert data['valid_bindings'] >= 0def test_metacheck_pipeline_execution():    """Проверяет, что Layer 4 успешно читает отчёт и не падает с ошибками"""    from validator.ts_layer4_metacheck import run_metacheck    # Убеждаемся, что отчёт есть    if not os.path.exists('ts_sandbox_report.json'):        from validator.ts_d_sandbox import DSandbox        DSandbox(iterations=10).run_selfplay()    result = run_metacheck()    # Функция должна вернуть bool, а не выбросить исключение    assert isinstance(result, bool)import yaml, os, pytestdef _load_yaml(path):    """Безопасная загрузка YAML"""    full_path = os.path.join(os.path.dirname(__file__), "..", path)    with open(full_path, encoding="utf-8") as f:        return yaml.safe_load(f)def test_subact_inheritance():    """ПодАкт наследует все инварианты базового акта (PR_Ω, Γ_Locality)"""    base = _load_yaml("contracts/domains/TS-Physics_2.0/act_2.0.yaml")    sub = _load_yaml("contracts/domains/TS-Physics_2.0/subacts/superconductivity_2.1.yaml")        assert sub.get("based_on") == "2.0", "ПодАкт должен явно указывать based_on: '2.0'"    assert sub.get("subact_inherits", {}).get("all_invariants_from") == "2.0", "Требуется явное наследование инвариантов"        # Проверяем, что базовые Z-правила присутствуют или унаследованы    base_z = base.get("constitutional_invariants", {}).get("Z_rules", [])    sub_z = sub.get("constitutional_invariants", {}).get("domain_specific_Z", [])    # ПодАкт может добавлять свои Z, но не удалять базовые    assert len(base_z) > 0, "Базовый акт должен содержать Z_rules"    assert sub.get("validator_notes") and "Наследовать все инварианты из act_2.0.yaml" in sub["validator_notes"], \        "В validator_notes должно быть указано требование наследования"def test_subact_profiling_not_replacement():    """Профилирование не заменяет базовые уровни, а расширяет их (PR_Θ.Z2)"""    sub = _load_yaml("contracts/domains/TS-Physics_2.0/subacts/superconductivity_2.1.yaml")    levels = sub.get("levels", {})        required_levels = ["A", "B", "C", "D", "E"]    for lvl in required_levels:        assert lvl in levels, f"ПодАкт должен содержать уровень {lvl} (профилирование, не замена)"        assert levels[lvl], f"Уровень {lvl} не должен быть пустым"        # Проверяем, что нет редукции A-модальности в B/C (PR_Ω.Z1)    assert levels["A"].get("event_type") not in ["historical_record", "rule_enforcement"], \        "A-уровень ПодАкта не должен сводиться к B/C-модальности"def test_domain_specific_Z_compliance():    """Z_Phys.2 не противоречит базовым Z-правилам (Z_R.5, Z_HP)"""    sub = _load_yaml("contracts/domains/TS-Physics_2.0/subacts/superconductivity_2.1.yaml")    domain_z = sub.get("constitutional_invariants", {}).get("domain_specific_Z", [])        # 1. Проверка наличия обязательных доменных запретов    assert "Z_Phys.1" in domain_z, "ПодАкт должен содержать Z_Phys.1"    assert "Z_Phys.2" in domain_z, "ПодАкт сверхпроводимости должен содержать Z_Phys.2"        # 2. Проверка формата: доменные правила не должны маскироваться под ядерные    for rule in domain_z:        rule_str = str(rule)        assert not rule_str.startswith("Z-"), f"Доменное правило '{rule_str}' не должно начинаться с 'Z-' (зарезервировано для ядра KVS)"